#include "tapas/textension.h"

#include "../arguments.h"
#include "../iterables.h"
#include "../ranges.h"

#include "tapas/objects/titer.h"
#include "tapas/objects/tlist.h"
#include "tapas/objects/tstr.h"
#include "tapas/dsa/tstring.h"

#include <limits.h>

/* Iterator indices are immutable. Keep List writes in native storage while
 * preserving the same bounds and reference ownership as individual writes. */
static void fill_list_range(tlist *list, const tobj *value, const titer *range)
{
	long index = range->start;
	long step = range->step;
	long length = (long)tlist_size(list);
	int scalar = value->type != tcompo && list->items.compo_count == 0;
	tstdlib_range checked;
	if (scalar && tstdlib_range_in_bounds(range, length, &checked)) {
		long position = checked.start;
		for (size_t remaining = checked.count; remaining; remaining--) {
			list->items.data[position] = *value;
			if (remaining > 1)
				position += checked.step;
		}
		return;
	}
	if (!step)
		return;
	while (step > 0 ? index < range->end : index > range->end) {
		long position = index < 0 ? index + length : index;
		if (position < 0 || position >= length)
			twarn(ErrRuntime_IdxOutRange, "fill", "List index out of range");
		if (scalar)
			list->items.data[position] = *value;
		else
			tobj_vec_set(&list->items, (uint_count)position, value);
		/* The mathematical next index can lie outside Int. In that case
		 * it also lies beyond the representable exclusive endpoint. */
		if ((step > 0 && index > LONG_MAX - step) ||
		    (step < 0 && index < LONG_MIN - step))
			break;
		index += step;
	}
}

static void builtin_fill(tobj *params, uint_regs len, tobj *result)
{
	tstdlib_require_arguments("fill", len, 3);
	tcompo_v *target = params[0].type == tcompo ? params[0].val.v_tcompo : nullptr;
	if (!target || !target->vtable->capabilities ||
	    !target->vtable->capabilities->index_settable)
		twarn(ErrRuntime_ParamsType, "fill", "IndexSettable required");
	tcompo_v *indices = tstdlib_require_iterable(&params[2], "fill");
	const tcompo_bulk_operations *bulk = target->vtable->bulk_operations;
	if (bulk && bulk->fill && bulk->fill(target, &params[1], indices)) {
		tobj_set_nil(result);
		return;
	}
	if (target->vtable == &tlist_vtable && indices->vtable == &titer_vtable) {
		fill_list_range((tlist *)target, &params[1], (const titer *)indices);
	} else {
		long position = 0;
		tobj key;
		tobj_set_nil(&key);
		while (tcompo_next(indices, &position, &key)) {
			if (target->vtable == &tlist_vtable) {
				tlist *list = (tlist *)target;
				if (key.type != tint) {
					tobj_ddc_ref_clear(&key);
					twarn(ErrRuntime_ParamsType, "fill", "List index must be Int");
				}
				long index = key.val.v_tint;
				tobj_ddc_ref_clear(&key);
				long length = (long)tlist_size(list);
				if (index < 0)
					index += length;
				if (index < 0 || index >= length)
					twarn(ErrRuntime_IdxOutRange, "fill", "List index out of range");
				tobj_vec_set(&list->items, (uint_count)index, &params[1]);
			} else {
				tcompo_index_set(target, &key, 1, &params[1]);
				tobj_ddc_ref_clear(&key);
			}
		}
	}
	tobj_set_nil(result);
}

/* Scalar identical comparisons can be inlined without invoking overloaded
 * equality or converting numeric Types. Other values keep the generic path. */
static long count_list(const tlist *list, const tobj *value)
{
	long count = 0;
	if (value->type == tbool) {
		for (uint_count i = 0; i < list->items.len; i++) {
			const tobj *item = &list->items.data[i];
			count += item->type == tbool && item->val.v_tbool == value->val.v_tbool;
		}
	} else if (value->type == tint) {
		for (uint_count i = 0; i < list->items.len; i++) {
			const tobj *item = &list->items.data[i];
			count += item->type == tint && item->val.v_tint == value->val.v_tint;
		}
	} else if (value->type == tfloat) {
		for (uint_count i = 0; i < list->items.len; i++) {
			const tobj *item = &list->items.data[i];
			count += item->type == tfloat && item->val.v_tfloat == value->val.v_tfloat;
		}
	} else {
		for (uint_count i = 0; i < list->items.len; i++)
			count += tobj_identical(&list->items.data[i], value);
	}
	return count;
}

static long count_string(const tstr *string, const tobj *value)
{
	/* String iteration yields one-byte Strings, including embedded NULs. */
	if (tobj_compo_type(value) != compo_tstr)
		return 0;
	const tstr *needle = (const tstr *)value->val.v_tcompo;
	if (tstring_len(needle->data) != 1)
		return 0;
	char byte = tstring_cstr(needle->data)[0];
	const char *data = tstring_cstr(string->data);
	long count = 0;
	size_t length = tstring_len(string->data);
	for (size_t i = 0; i < length; i++)
		count += data[i] == byte;
	return count;
}

static void builtin_count(tobj *params, uint_regs len, tobj *result)
{
	tstdlib_require_arguments("count", len, 2);
	tcompo_v *values = tstdlib_require_iterable(&params[0], "count");
	long count = 0;
	const tcompo_bulk_operations *bulk = values->vtable->bulk_operations;
	if (bulk && bulk->count && bulk->count(values, &params[1], &count)) {
		/* The implementation uses the same identical semantics as iteration. */
	} else if (values->vtable == &tlist_vtable) {
		count = count_list((const tlist *)values, &params[1]);
	} else if (values->vtable == &tstr_vtable) {
		count = count_string((const tstr *)values, &params[1]);
	} else {
		long position = 0;
		tobj item;
		tobj_set_nil(&item);
		while (tcompo_next(values, &position, &item)) {
			int match = tobj_identical(&item, &params[1]);
			tobj_ddc_ref_clear(&item);
			if (match && count == LONG_MAX)
				twarn(ErrRuntime_IntOutOfRange, "count", "result exceeds Int");
			count += match;
		}
	}
	tobj_set_int(result, count);
}

static const textension_symbol symbols[] = {
	{
		.name = "fill",
		.type = "Function[IndexSettable, AnyType, Iterable] -> Nil",
		.detail = "fill(target: IndexSettable, value: AnyType, indices: Iterable) -> Nil",
		.kind = textension_function,
		.function = builtin_fill,
		.minimum_arguments = 3,
		.maximum_arguments = 3
	},
	{
		.name = "count",
		.type = "Function[Iterable, AnyType] -> Int",
		.detail = "count(values: Iterable, value: AnyType) -> Int",
		.kind = textension_function,
		.function = builtin_count,
		.minimum_arguments = 2,
		.maximum_arguments = 2
	}
};

const textension_module tstdlib_bulk_functions = {
	.scope = textension_root,
	.symbols = symbols,
	.symbol_count = sizeof(symbols) / sizeof(symbols[0])
};

src/stdlib/compact.c.source:
#include "compact.h"
#include "ranges.h"

#include "tapas/dsa/tstring.h"

#include <limits.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

static size_t item_size(tcompact_kind kind)
{
	return kind == tcompact_real ? sizeof(double) : 1;
}

tcompact *tcompact_new(tcompo_vtable *vtable, tcompact_kind kind, size_t length,
			 tcompo_v *owner, void *data)
{
	if (length > LONG_MAX || length > SIZE_MAX / item_size(kind))
		twarn(ErrRuntime_IntOutOfRange, "compact sequence", "length exceeds Int");
	tcompact *sequence = calloc(1, sizeof(*sequence));
	if (!sequence)
		twarn(ErrRuntime_Other, "compact sequence", "out of memory");
	sequence->base.vtable = vtable;
	sequence->kind = kind;
	sequence->length = length;
	sequence->owner = owner;
	if (owner) {
		owner->refctr++;
		sequence->data = data;
	} else if (length) {
		sequence->data = malloc(length * item_size(kind));
		if (!sequence->data) {
			free(sequence);
			twarn(ErrRuntime_Other, "compact sequence", "out of memory");
		}
	}
	return sequence;
}

long tcompact_len(void *self)
{
	return (long)((tcompact *)self)->length;
}

void *tcompact_copy(void *self)
{
	tcompact *source = self;
	tcompact *copy = tcompact_new(source->base.vtable, source->kind,
				     source->length, nullptr, nullptr);
	if (source->length)
		memcpy(copy->data, source->data, source->length * item_size(source->kind));
	return copy;
}

void tcompact_free(void *self)
{
	tcompact *sequence = self;
	if (sequence->owner) {
		tobj owner = {0};
		tobj_set_compo(&owner, sequence->owner);
		tobj_ddc_ref_clear(&owner);
	} else {
		free(sequence->data);
	}
	free(sequence);
}

int tcompact_identical(void *self, void *other)
{
	tcompact *a = self, *b = other;
	if (a->kind != b->kind || a->length != b->length)
		return 0;
	if (a->kind == tcompact_real) {
		const double *left = a->data, *right = b->data;
		for (size_t i = 0; i < a->length; i++)
			if (left[i] != right[i])
				return 0;
		return 1;
	}
	return !a->length || memcmp(a->data, b->data, a->length) == 0;
}

tstring *tcompact_string(void *self)
{
	tcompact *sequence = self;
	return tobj_tostring_pointer(sequence->base.vtable->get_type(), self);
}

static int index_position(const tcompact *sequence, const tobj *arguments,
			  uint_regs count, long *position)
{
	if (count != 1)
		twarn(ErrRuntime_ParamsCtr, "compact sequence index", "one index required");
	if (arguments[0].type != tint)
		twarn(ErrRuntime_ParamsType, "compact sequence index", "Int required");
	*position = arguments[0].val.v_tint;
	if (*position < 0)
		*position += (long)sequence->length;
	return *position >= 0 && (size_t)*position < sequence->length;
}

static void read_item(const tcompact *sequence, size_t position, tobj *result)
{
	if (sequence->kind == tcompact_real)
		tobj_set_float(result, ((double *)sequence->data)[position]);
	else if (sequence->kind == tcompact_bool)
		tobj_set_bool(result, ((unsigned char *)sequence->data)[position] != 0);
	else
		tobj_set_int(result, ((unsigned char *)sequence->data)[position]);
}

static int compact_try_index(void *self, const tobj *arguments,
			     uint_regs count, tobj *result)
{
	long position;
	if (!index_position(self, arguments, count, &position))
		return 0;
	read_item(self, (size_t)position, result);
	return 1;
}

static void compact_index(void *self, const tobj *arguments,
			  uint_regs count, tobj *result)
{
	if (!compact_try_index(self, arguments, count, result))
		twarn(ErrRuntime_IdxOutRange, "compact sequence index", "index out of range");
}

static double write_value(const tcompact *sequence, const tobj *value)
{
	if (sequence->kind == tcompact_real && (value->type == tint || value->type == tfloat))
		return value->type == tint ? (double)value->val.v_tint : value->val.v_tfloat;
	if (sequence->kind == tcompact_bool && value->type == tbool)
		return value->val.v_tbool != 0;
	if (sequence->kind == tcompact_byte && value->type == tint &&
	    value->val.v_tint >= 0 && value->val.v_tint <= 255)
		return (double)value->val.v_tint;
	twarn(ErrRuntime_ParamsType, "compact sequence write", "value does not match storage type");
	return 0;
}

static void compact_set(void *self, const tobj *arguments,
			uint_regs count, const tobj *value)
{
	tcompact *sequence = self;
	long position;
	if (!index_position(sequence, arguments, count, &position))
		twarn(ErrRuntime_IdxOutRange, "compact sequence write", "index out of range");
	double replacement = write_value(sequence, value);
	if (sequence->kind == tcompact_real)
		((double *)sequence->data)[position] = replacement;
	else
		((unsigned char *)sequence->data)[position] = (unsigned char)replacement;
}

static int compact_next(void *self, long *position, tobj *result)
{
	tcompact *sequence = self;
	if (*position < 0 || (size_t)*position >= sequence->length)
		return 0;
	read_item(sequence, (size_t)(*position)++, result);
	return 1;
}

static int compact_count(void *self, const tobj *value, long *result)
{
	tcompact *sequence = self;
	long count = 0;
	if (sequence->kind == tcompact_real) {
		if (value->type == tfloat) {
			const double *data = sequence->data;
			for (size_t i = 0; i < sequence->length; i++)
				count += data[i] == value->val.v_tfloat;
		}
	} else {
		int valid = sequence->kind == tcompact_bool ? value->type == tbool :
			value->type == tint && value->val.v_tint >= 0 && value->val.v_tint <= 255;
		if (valid) {
			unsigned char key = sequence->kind == tcompact_bool ?
				(unsigned char)value->val.v_tbool : (unsigned char)value->val.v_tint;
			const unsigned char *data = sequence->data;
			for (size_t i = 0; i < sequence->length; i++)
				count += data[i] == key;
		}
	}
	*result = count;
	return 1;
}

static int compact_contains(void *self, const tobj *value)
{
	long count;
	compact_count(self, value, &count);
	return count != 0;
}

static int compact_fill(void *self, const tobj *value, const tcompo_v *indices)
{
	tcompact *sequence = self;
	if (indices->vtable != &titer_vtable)
		return 0;
	tstdlib_range range;
	if (!tstdlib_range_in_bounds((const titer *)indices, (long)sequence->length, &range))
		return 0;
	if (!range.count)
		return 1;
	double replacement = write_value(sequence, value);
	if (sequence->kind != tcompact_real && (range.step == 1 || range.step == -1)) {
		long first = range.step > 0 ? range.start : range.start - (long)(range.count - 1);
		memset((unsigned char *)sequence->data + first, (unsigned char)replacement, range.count);
		return 1;
	}
	long position = range.start;
	if (sequence->kind == tcompact_real) {
		double *data = sequence->data;
		for (size_t remaining = range.count; remaining; remaining--) {
			data[position] = replacement;
			if (remaining > 1)
				position += range.step;
		}
	} else {
		unsigned char *data = sequence->data;
		for (size_t remaining = range.count; remaining; remaining--) {
			data[position] = (unsigned char)replacement;
			if (remaining > 1)
				position += range.step;
		}
	}
	return 1;
}

const tcompo_capabilities tcompact_capabilities = {
	.indexable = compact_index,
	.try_indexable = compact_try_index,
	.index_settable = compact_set,
	.contains = compact_contains,
	.iterable = compact_next
};

const tcompo_bulk_operations tcompact_bulk_operations = {
	.fill = compact_fill,
	.count = compact_count
};

