{
	tstdlib_require_arguments("math::abs", len, 1);
	if (params[0].type == tint)
		tobj_set_int(vre, labs(params[0].val.v_tint));
	else
		tobj_set_float(vre, fabs(math_arg_double(&params[0], "math::abs")));
}

